async function startNew(){record=newRecord();record.sequence=await nextSequence();record.academicYear=school.year;record.committee.chair=(school.assistantPrincipals||[]).find(Boolean)||school.principal||"";record.committee.principal=school.principal||"";dirty=true;page="identity";render()}
async function saveRecord(show=true){record.committee.principal=school.principal||"";if(!record.committee.chair)record.committee.chair=(school.assistantPrincipals||[]).find(Boolean)||school.principal||"";if(!record.student.name.trim()){if(show)alert("Öğrencinin adı soyadı girilmelidir.");return false}if(!/^\d{10}[02468]$/.test(String(record.student.tc||""))){page="identity";render();const tc=document.querySelector("[data-path='student.tc']");if(tc){tc.classList.add("invalid-input");tc.focus()}if(show)alert("T.C. Kimlik Numarası 11 rakamdan oluşmalı ve çift rakamla bitmelidir.");return false}if(!record.id){record.id=uid();record.sequence=await nextSequence();record.createdAt=new Date().toISOString()}record.updatedAt=new Date().toISOString();record.academicYear=record.academicYear||school.year;await req(tx(STORE,"readwrite").put(clone(record)));dirty=false;await loadAll();if(show)toast("Öğrenci ve BEP planı veritabanına kaydedildi");render();return true}
async function deleteRecord(id){if(!confirm("Bu öğrenciye ait seçili eğitim yılı kaydı silinsin mi?"))return;await req(tx(STORE,"readwrite").delete(id));record=newRecord();record.academicYear=school.year;await loadAll();page="students";render()}
async function clearAnnualBepData(){if(!records.length){alert("Temizlenecek öğrenci kaydı bulunamadı.");return}const password=prompt("Yıllık BEP verilerini temizlemek için şifreyi girin:");if(password===null)return;if(password!=="0000"){alert("Şifre yanlış. Hiçbir veri silinmedi.");return}if(!confirm(records.length+" öğrenci kaydındaki yıllık BEP planı, hizmet, karar, toplantı, komisyon ve kapak verileri temizlenecek.\n\nKimlik/sınıf/nüfus, aile bilgileri, geçmiş-sağlık-düzenlemeler ve eğitsel performans korunacak. Devam edilsin mi?"))return;const activeId=record.id;for(const source of records){const x=normalizeRecord(clone(source)),fresh=newRecord();x.services=[];x.decisions=fresh.decisions;x.committee=fresh.committee;x.committee.chair=(school.assistantPrincipals||[]).find(Boolean)||school.principal||"";x.committee.classTeacher=x.student.teacher||"";x.committee.principal=school.principal||"";x.meeting=fresh.meeting;x.plan=fresh.plan;x.cover=fresh.cover;x.updatedAt=new Date().toISOString();await req(tx(STORE,"readwrite").put(x))}await loadAll();if(activeId){const active=records.find(x=>x.id===activeId);if(active)record=clone(active)}page="students";dirty=false;render();alert("Yıllık BEP verileri temizlendi. Korunması istenen öğrenci, aile, sağlık/geçmiş ve eğitsel performans bilgileri bırakıldı.")}
async function selectRecord(id){const x=await req(tx(STORE).get(id));if(x){record=normalizeRecord(x);dirty=false;page="identity";render();scrollTo(0,0)}}
async function switchRecord(id){if(!id||id===record.id)return;const targetPage=page;if(dirty&&record.student.name)await saveRecord(false);const x=await req(tx(STORE).get(id));if(x&&(!activeTeacher||teacherAllowedRecord(x))){record=normalizeRecord(x);dirty=false;activePlanCourse="";page=targetPage;render();scrollTo(0,0)}}
async function promoteRecord(id){const src=await req(tx(STORE).get(id));if(!src)return;const x=merge(emptyRecord(),clone(src));x.id=null;x.academicYear=nextYearLabel(src.academicYear);x.student.classBranch=promoteClass(src.student.classBranch);x.student.bepStart=today();x.student.bepEnd=defaultEnd();x.decisions.nextMeeting="";x.decisions.generalEvaluation="";x.cover.date="";x.plan.rows=x.plan.rows.map(r=>Object.assign({},r,{evaluationDates:"",status:""}));record=x;dirty=true;page="identity";render();toast("Yeni eğitim yılı kopyası hazırlandı; kaydettiğinizde yeni kayıt oluşur")}
function merge(a,b){if(Array.isArray(a))return Array.isArray(b)?b:a;if(a&&typeof a==="object"){const o={};[...new Set([...Object.keys(a),...Object.keys(b&&typeof b==="object"?b:{})])].forEach(k=>o[k]=merge(a[k],b&&b[k]));return o}return b===undefined?a:b}
function arr(v){return Array.isArray(v)?v:(v?[String(v)]:[])}
function trimBlankRows(list,blank){const rows=(list||[]).filter(x=>Object.values(x||{}).some(v=>Array.isArray(v)?v.length:String(v??"").trim()));return rows.length?rows:[blank()]}
function normalizeRecord(x){x=merge(emptyRecord(),x);x.student.gender=normalizeGender(x.student.gender);x.student.diagnoses=arr(x.student.diagnoses.length?x.student.diagnoses:x.student.diagnosis);x.performance=trimBlankRows(x.performance,()=>({area:"",level:""}));x.services=(x.services||[]).filter(s=>s.area||s.weekly||s.responsible||arr(s.types||s.type).length).map(s=>Object.assign({},s,{types:arr(s.types&&s.types.length?s.types:s.type)}));x.decisions.other=(x.decisions.other||[]).filter(Boolean);if(!x.decisions.other.length)x.decisions.other=[""];x.decisions.nextMeeting=x.decisions.nextMeeting||defaultNextMeeting();x.decisions.familyChannel=arr(x.decisions.familyChannel);x.decisions.familyEducationChannel=arr(x.decisions.familyEducationChannel);const normalizeGoal=r=>Object.assign(goalRow(),r,{methods:arr(r.methods),materials:arr(r.materials),evaluationMethod:arr(r.evaluationMethod)});x.plan.rows=x.plan.rows.map(normalizeGoal);x.plan.byCourse=x.plan.byCourse||{};if(!Object.keys(x.plan.byCourse).length&&(x.plan.course||x.performance.some(p=>p.area))){const name=x.plan.course||x.performance.find(p=>p.area).area;x.plan.byCourse[name]={environmentArrangement:x.plan.environmentArrangement||"",rows:x.plan.rows.length?x.plan.rows:[goalRow()]}}Object.keys(x.plan.byCourse).forEach(k=>{x.plan.byCourse[k].rows=(x.plan.byCourse[k].rows||[goalRow()]).map(normalizeGoal)});return x}
const baseNormalizeRecord=normalizeRecord;normalizeRecord=function(x){x=baseNormalizeRecord(x);x.performance=x.performance.map(p=>Object.assign({area:"",level:"",skillArea:"",skillAreas:[],selectedLongTerms:[],achievements:[]},p,{skillAreas:arr(p.skillAreas?.length?p.skillAreas:p.skillArea),selectedLongTerms:arr(p.selectedLongTerms),achievements:arr(p.achievements).map(a=>typeof a==="string"?{key:a,percentage:"%100"}:a)}));return x};
function performanceCourses(){return [...new Set(record.performance.map(x=>x.area.trim()).filter(Boolean))]}
function syncCoursePlans(){record.plan.byCourse=record.plan.byCourse||{};performanceCourses().forEach(c=>{if(!record.plan.byCourse[c])record.plan.byCourse[c]={teacher:"",environmentArrangement:"",rows:[goalRow()]};if(record.plan.byCourse[c].teacher===undefined)record.plan.byCourse[c].teacher=""});if(!activePlanCourse||!record.plan.byCourse[activePlanCourse])activePlanCourse=performanceCourses()[0]||Object.keys(record.plan.byCourse)[0]||""}
const esc=v=>String(v??"").replace(/[&<>\"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function get(path){return path.split(".").reduce((o,k)=>o&&o[k],record)??""}
function put(path,value){const ks=path.split("."),last=ks.pop();let o=record;ks.forEach(k=>o=o[k]);o[last]=value;dirty=true;state("Kaydedilmemiş değişiklik")}
function state(t){document.querySelector("#saveText").textContent=t;document.querySelector("#saveDot").style.background=dirty?"#f2bd61":"#73d5ae"}
function goToPage(target){page=target;render();scrollTo(0,0)}
const TEACHER_EDIT_PAGES=["identity","performance","plan"],TEACHER_ONLY_VISIBLE=["home","students","support","agenda","messages","identity","performance","plan","previews"];
function nav(){const menu=document.querySelector("#nav"),visible=activeTeacher?steps.filter(x=>x[0]!=="stats"&&(teacherShowReadonly||TEACHER_ONLY_VISIBLE.includes(x[0]))):steps;menu.innerHTML="<div class='nav-group'>BEP İş Akışı</div>"+visible.map(x=>{const editable=TEACHER_EDIT_PAGES.includes(x[0]);return "<button type='button' class='nav-btn "+(x[0]===page?"active ":"")+(activeTeacher?(editable?"teacher-editable":"teacher-readonly"):"")+"' data-nav-page='"+x[0]+"' data-teacher-page-mode='"+(editable?"editable":"readonly")+"'><span class='nav-badge'>"+x[2]+"</span>"+x[1]+"</button>"}).join("")+(activeTeacher?"<button id='teacherLogout' class='nav-btn logout'>Öğretmen çıkışı</button>":"<button class='nav-btn' data-nav-page='teachers'>Derse Giren Öğretmenler</button>");menu.onclick=event=>{const button=event.target.closest("[data-nav-page]");if(button){if(activeTeacher&&button.dataset.teacherPageMode==="readonly"&&!['home','previews'].includes(button.dataset.navPage))alert("Bu sayfadaki bilgiler yalnızca görüntülenebilir. Değişiklik yapamazsınız.");goToPage(button.dataset.navPage)}if(event.target.closest('#teacherLogout')){activeTeacher=null;teacherShowReadonly=true;location.hash='';loadAll().then(()=>{page='home';render()})}}}
function field(label,path,type="text",cls="",hint=""){const v=esc(get(path));const control=type==="textarea"?"<textarea data-path='"+path+"'>"+v+"</textarea>":"<input data-path='"+path+"' type='"+type+"' value='"+v+"'>";return "<div class='field "+cls+"'><label>"+label+"</label>"+control+(hint?"<small>"+hint+"</small>":"")+"</div>"}
function tcField(){return "<div class='field id-tc'><label>T.C. kimlik numarası</label><input data-path='student.tc' data-tc-input type='text' inputmode='numeric' maxlength='11' pattern='[0-9]{10}[02468]' value='"+esc(record.student.tc)+"' aria-describedby='tcHint'><small id='tcHint'>11 hane olmalı ve çift rakamla bitmelidir.</small></div>"}
function selectField(label,path,options,cls=""){const current=String(get(path)),list=options.filter(Boolean);if(current&&!list.includes(current))list.unshift(current);return "<div class='field "+cls+"'><label>"+label+"</label><select data-path='"+path+"'><option value=''>Seçiniz</option>"+list.map(x=>"<option value='"+esc(x)+"' "+(x===current?"selected":"")+">"+esc(x)+"</option>").join("")+"</select></div>"}
function courseField(label,path,cls=""){return "<div class='field "+cls+"'><label>"+label+"</label><input data-path='"+path+"' data-course-input list='courseList' value='"+esc(get(path))+"' placeholder='Ders ara veya yeni ad yaz'><datalist id='courseList'>"+school.courses.map(x=>"<option value='"+esc(x)+"'>").join("")+"</datalist></div>"}
function multiField(label,path,options,cls=""){const selected=arr(get(path));return "<div class='field "+cls+"'><label>"+label+" (birden fazla seçilebilir)</label><select multiple size='5' data-multi-path='"+path+"'>"+options.map(x=>"<option value='"+esc(x)+"' "+(selected.includes(x)?"selected":"")+">"+esc(x)+"</option>").join("")+"</select><small>Birden fazla seçim için Ctrl tuşunu basılı tutun.</small></div>"}
function sfield(label,key,type="text",cls=""){const v=esc(school[key]||"");return "<div class='field "+cls+"'><label>"+label+"</label><input data-school='"+key+"' type='"+type+"' value='"+v+"'></div>"}
function sarray(label,key,count){return Array.from({length:count},(_,i)=>"<div class='field'><label>"+label+" "+(i+1)+"</label><input data-school-array='"+key+"' data-index='"+i+"' value='"+esc((school[key]||[])[i]||"")+"'></div>").join("")}
function classEditor(){const rows=(school.classes||[]).map((x,i)=>"<div class='class-entry'><div class='class-name-cell'><span class='mobile-field-label'>Sınıf / Şube</span><input data-class-name='"+i+"' value='"+esc(x.name)+"' placeholder='Örn. 3/A'></div><div class='class-detail-cell'><label><span>Sınıf öğretmeni</span><input data-class-teacher='"+i+"' value='"+esc(x.teacher)+"' placeholder='Öğretmenin adı soyadı'></label><label><span>Sınıf düzeyi</span><select data-class-level='"+i+"'><option value=''>Seçiniz</option>"+CLASS_LEVELS.map(v=>"<option "+(x.level===v?"selected":"")+" value='"+v+"'>"+v+"</option>").join("")+"</select></label><label><span>Eğitim saati</span><select data-class-schedule='"+i+"'><option value=''>Seçiniz</option>"+EDUCATION_TIMES.map(v=>"<option "+(x.schedule===v?"selected":"")+" value='"+v+"'>"+v+"</option>").join("")+"</select></label><button data-remove-class='"+i+"' class='danger class-remove'>Sınıfı çıkar</button></div></div>").join("");return "<div class='class-bulk full'><div><strong>Kademeye göre toplu eğitim saati</strong><small>Seçilen düzeydeki bütün sınıflara aynı eğitim saatini uygular.</small></div><select id='bulkClassLevel'><option value=''>Sınıf düzeyi seçin</option>"+CLASS_LEVELS.map(v=>"<option value='"+esc(v)+"'>"+esc(v)+"</option>").join("")+"</select><select id='bulkClassSchedule'><option value=''>Eğitim saati seçin</option>"+EDUCATION_TIMES.map(v=>"<option value='"+esc(v)+"'>"+esc(v)+"</option>").join("")+"</select><button id='applyBulkSchedule'>Tümüne uygula</button></div><div class='class-sheet full'><div class='class-sheet-head'><strong>Sınıf / Şube</strong><span>Eklenen sınıfın bilgileri</span></div><div class='class-sheet-body'>"+(rows||"<div class='empty class-empty'>Henüz sınıf eklenmedi.</div>")+"</div><div class='class-add-row'><button id='addClass'>+ Yeni sınıf satırı ekle</button></div></div>"}
