function footer(){const i=steps.findIndex(x=>x[0]===page),credit="<div class='developer-credit'>Programı geliştiren: Adem DEĞERLİ · <a href='mailto:ademdegerli@gmail.com'>ademdegerli@gmail.com</a></div>";if(i<0)return credit;return "<div class='wizard-footer'>"+(i>0?"<button data-go='"+steps[i-1][0]+"' class='ghost'>← Önceki</button>":"<span></span>")+"<div class='step-count'>"+(i+1)+" / "+steps.length+"</div>"+(i<steps.length-1?"<button data-go='"+steps[i+1][0]+"' class='primary'>Devam →</button>":"<span></span>")+"</div>"+credit}
function homePage(){const unique=new Set(records.map(x=>x.student.tc||x.student.name)).size,support=records.filter(isSupport).length;return "<section class='hero'><div><h2>BEP çalışma alanı</h2><p>Öğrenci kayıtlarını, BEP planlarını, toplantı kararlarını ve çıktıları tek yerden yönetin.</p></div></section><div class='home-stats'><button data-page='students'><strong>"+records.length+"</strong><span>BEP kaydı</span></button><button data-page='students'><strong>"+unique+"</strong><span>öğrenci</span></button><button data-page='support'><strong>"+support+"</strong><span>destek eğitim kaydı</span></button></div><div class='home-grid'><button id='homeNew' class='home-action'><strong>Yeni öğrenci ekle</strong><span>Kimlik ve sınıf bilgileriyle başlayın.</span></button><button data-page='students' class='home-action'><strong>Öğrenci / BEP ara</strong><span>Eski kayıtları açın ve güncelleyin.</span></button><button data-page='school' class='home-action'><strong>Okul bilgileri</strong><span>Sınıf, öğretmen, yönetici ve logo ayarları.</span></button><button data-page='stats' class='home-action'><strong>İstatistikler</strong><span>Sınıf, engel türü, grup ve toplantı dağılımlarını inceleyin.</span></button><button data-page='previews' class='home-action'><strong>Çıktılar</strong><span>Tek veya toplu PDF hazırlayın.</span></button></div>"+footer()}
function bepPreparedInfo(x){const plans=Object.values(x.plan?.byCourse||{}),filled=plans.filter(p=>arr(p.rows).some(r=>String(r.longTerm||r.shortTerm||"").trim())),teachers=[...new Set(filled.map(p=>String(p.teacher||"").trim()).filter(Boolean))];return {prepared:filled.length>0,teachers:teachers.length?teachers:[x.student.teacher].filter(Boolean)}}
function bepPreparationPanel(){if(activeTeacher)return "";const rows=[...records].sort((a,b)=>String(a.student.classBranch||"").localeCompare(String(b.student.classBranch||""),"tr",{numeric:true})||String(a.student.name||"").localeCompare(String(b.student.name||""),"tr")).map(x=>{const info=bepPreparedInfo(x);return "<tr><td>"+esc(x.student.classBranch||"—")+"</td><td><strong>"+esc(x.student.name||"Adsız öğrenci")+"</strong></td><td>"+esc(info.teachers.join(", ")||"Öğretmen bilgisi yok")+"</td><td><span class='bep-state "+(info.prepared?"ready":"missing")+"'>"+(info.prepared?"Hazırlandı":"Hazırlanmadı")+"</span></td><td><button data-open='"+x.id+"'>BEP'i aç</button></td></tr>"}).join(""),ready=records.filter(x=>bepPreparedInfo(x).prepared).length;return "<article class='card bep-preparation-card'><div class='card-head'><div><h2>BEP hazırlık durumu</h2><p>Hangi öğrencinin BEP'inin hazırlandığını ve sorumlu öğretmeni buradan izleyebilirsiniz.</p></div><div class='bep-summary'><b>"+ready+" hazır</b><b>"+(records.length-ready)+" hazırlanmadı</b></div></div><div class='card-body table-wrap'><table><thead><tr><th>Sınıf</th><th>Öğrenci</th><th>Öğretmen</th><th>Durum</th><th></th></tr></thead><tbody>"+(rows||"<tr><td colspan='5'>Henüz öğrenci kaydı yok.</td></tr>")+"</tbody></table></div></article>"}
const baseHomePage=homePage;homePage=function(){const portal="<article class='card teacher-portal-card'><div class='card-head'><div><h2>Öğretmen girişi</h2><p>Öğretmenler kendilerine verilen şifreyle yalnızca yetkili oldukları öğrencilere erişebilir.</p></div>"+(!activeTeacher?"<button data-page='teacherLogin' class='primary'>Öğretmen giriş sayfası</button>":"<strong>"+esc(activeTeacher.name)+"</strong>")+"</div>"+(!activeTeacher?"<div class='card-body'><code>"+esc(teacherPortalLink())+"</code><button data-page='teacherMessage'>Öğretmene gönderilecek mesaj</button></div>":"")+"</article>";return baseHomePage().replace("<div class='developer-credit'>",portal+teacherPersonalGoalPanel()+bepPreparationPanel()+"<div class='developer-credit'>")};
function countBy(values){const map=new Map();values.filter(Boolean).forEach(v=>map.set(v,(map.get(v)||0)+1));return [...map].sort((a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0]),"tr",{numeric:true,sensitivity:"base"}))}
function statBars(title,items,emptyText="Kayıt bulunamadı"){const max=Math.max(1,...items.map(x=>x[1]));return "<article class='card stat-card'><div class='card-head'><h2>"+esc(title)+"</h2></div><div class='card-body stat-bars'>"+(items.map(([label,count])=>"<div class='stat-row'><span title='"+esc(label)+"'>"+esc(label)+"</span><div><i style='width:"+(count/max*100).toFixed(1)+"%'></i></div><strong>"+count+"</strong></div>").join("")||"<p class='empty-inline'>"+esc(emptyText)+"</p>")+"</div></article>"}
function statsPage(){const ramRecords=records.filter(isRamClassMismatch),regular=records.filter(x=>!isRamClassMismatch(x)),scheduled=regular.filter(x=>x.meeting?.planDay&&x.meeting?.time).length,support=regular.filter(isSupport).length;return "<section class='hero'><div><h2>BEP istatistikleri</h2><p>RAM sınıf kademesi uyarısı bulunan öğrenciler diğer kayıtlardan ayrı hesaplanır.</p></div></section><div class='stats-summary'><div><strong>"+regular.length+"</strong><span>Diğer öğrenci kayıtları</span></div><div class='warning'><strong>"+ramRecords.length+"</strong><span>RAM kademe uyarılı öğrenci</span></div><div><strong>"+support+"</strong><span>Özel eğitim / destek kaydı</span></div><div><strong>"+scheduled+"</strong><span>Planlı toplantı</span></div></div><div class='stats-grid'>"+statBars("Diğer öğrenciler — sınıflara göre",countBy(regular.map(x=>x.student.classBranch)))+statBars("RAM uyarılı öğrenciler — sınıflara göre",countBy(ramRecords.map(x=>x.student.classBranch)))+statBars("Diğer öğrenciler — engel türleri",countBy(regular.flatMap(x=>arr(x.student.diagnoses))))+statBars("RAM uyarılı öğrenciler — engel türleri",countBy(ramRecords.flatMap(x=>arr(x.student.diagnoses))))+"</div>"+footer()}
function schoolPage(){const logo=school.logo?"<img class='logo-preview' src='"+school.logo+"' alt='Okul logosu'>":"<div class='logo-empty'>Logo yüklenmedi</div>";return "<section class='hero'><div><h2>Tüm öğrenciler için ortak okul bilgileri</h2><p>Sınıfları öğretmenleriyle ekleyebilir; ders, engel, yöntem ve aile eğitimi listelerini düzenleyebilirsiniz.</p></div></section>"+goalLibraryPanel()+card("Okul ve eğitim yılı",sfield("Üst kurum / ülke","country")+sfield("Valilik","governorship")+sfield("Okul adı","name","text","half")+sfield("Eğitim ve öğretim yılı","year","text","half")+sfield("Dosya başlığı","fileTitle","text","full")+"<div class='field full'><label>Okul logosu</label><div class='logo-control'>"+logo+"<label class='button ghost'>Logo yükle<input id='logoInput' type='file' accept='image/png,image/jpeg,image/webp' hidden></label>"+(school.logo?"<button id='removeLogo' class='danger'>Logoyu kaldır</button>":"")+"</div></div>")+card("Sınıflar ve sınıf öğretmenleri",classEditor(),"Değişiklikleri alttaki Okul bilgilerini kaydet düğmesiyle kaydedin")+card("Rehber öğretmenler",sarray("Rehber öğretmen","counselors",4))+card("Müdür yardımcıları ve okul müdürü",sarray("Müdür yardımcısı","assistantPrincipals",4)+sfield("Okul müdürü","principal","text","full"))+optionManagement()+"<div class='form-actions'><button id='saveSchool' class='primary'>Okul bilgilerini kaydet</button></div>"+footer()}
function classOptions(value){return "<option value=''>Tüm sınıflar</option>"+[...new Set(records.map(x=>x.student.classBranch).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"tr",{numeric:true,sensitivity:"base"})).map(x=>"<option value='"+esc(x)+"' "+(x===value?"selected":"")+">"+esc(x)+"</option>").join("")}
function isRamClassMismatch(x){return [x.student.group,x.student.recommendedService].map(importKey).some(v=>v.includes("ramraporsinifkademesiileeokulsinifkademesifarklidir"))}
async function bulkPromoteAll(){const source=records.filter(x=>x.academicYear===school.year),target=nextYearLabel(school.year);if(!source.length){alert("Mevcut okul eğitim yılına ait öğrenci kaydı bulunamadı.");return}const existing=new Set(records.filter(x=>x.academicYear===target).map(studentImportKey)),pending=source.filter(x=>!existing.has(studentImportKey(Object.assign({},x,{academicYear:target}))));if(!pending.length){alert("Bu öğrencilerin tamamı hedef eğitim yılında zaten kayıtlı.");return}if(!confirm(source.length+" öğrenciden "+pending.length+" tanesi "+target+" için bir üst sınıfa geçirilecek. Devam edilsin mi?"))return;let sequence=await nextSequence();for(const src of pending){const x=normalizeRecord(clone(src)),now=new Date().toISOString();x.id=uid();x.sequence=sequence++;x.academicYear=target;x.createdAt=now;x.updatedAt=now;x.student.classBranch=promoteClass(src.student.classBranch);x.student.bepStart=today();x.student.bepEnd=defaultEnd();x.decisions.nextMeeting="";x.decisions.generalEvaluation="";x.cover.date="";Object.values(x.plan.byCourse||{}).forEach(p=>(p.rows||[]).forEach(r=>{r.evaluationDates="";r.status=""}));const oldClass=(school.classes||[]).find(c=>c.name===src.student.classBranch);if(x.student.classBranch&&!school.classes.some(c=>c.name===x.student.classBranch))school.classes.push({name:x.student.classBranch,teacher:oldClass?.teacher||"",level:inferredClassLevel(x.student.classBranch),schedule:oldClass?.schedule||""});await req(tx(STORE,"readwrite").put(x))}await saveSchool();await loadAll();render();alert(pending.length+" öğrenci "+target+" için bir üst sınıfa geçirildi.")}
function rosterKey(x){const s=x.student||x;return s.number?"no|"+String(s.number).trim():"ad|"+importKey(s.name)+"|"+importKey(s.classBranch)}
function sameSet(a,b){const aa=[...new Set(arr(a))].sort(),bb=[...new Set(arr(b))].sort();return aa.length===bb.length&&aa.every((x,i)=>x===bb[i])}
async function parseStudentRoster(file){if(!globalThis.XLSX)throw new Error("Excel okuma bileşeni yüklenemedi.");const wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}),candidates=[];for(const sheetName of wb.SheetNames){const grid=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,defval:"",raw:false}),headerAt=grid.findIndex((row,i)=>i<25&&row.some(v=>["adisoyadi","ogrenciadisoyadi"].includes(importKey(v)))&&row.some(v=>["sinifisubesi","sinifsube"].includes(importKey(v))));if(headerAt>=0){const keys=grid[headerAt].map(importKey),score=[["ogrno","ogrencino","okulno"],["engeldurumu","engeldurumlari"],["onerilenhizmet"],["cinsiyeti","cinsiyet"]].filter(group=>group.some(k=>keys.includes(k))).length;candidates.push({sheetName,grid,headerAt,score})}}if(!candidates.length)throw new Error("IOG02009_99.XLS dosyasındaki öğrenci başlıkları bulunamadı.");const picked=candidates.sort((a,b)=>b.score-a.score)[0],headers=picked.grid[picked.headerAt].map(importKey),col=(...names)=>{for(const n of names){const i=headers.indexOf(n);if(i>=0)return i}return -1},idx={number:col("ogrno","ogrencino","okulno"),classBranch:col("sinifisubesi","sinifsube"),name:col("adisoyadi","ogrenciadisoyadi"),gender:col("cinsiyeti","cinsiyet"),diagnoses:col("engeldurumu","engeldurumlari"),service:col("onerilenhizmet")};if([idx.number,idx.classBranch,idx.name,idx.diagnoses,idx.service].some(i=>i<0))throw new Error("Dosyada Okul No, Sınıfı/Şubesi, Adı Soyadı, Engel Durumu veya Önerilen Hizmet sütunlarından biri eksik.");const raw=picked.grid.slice(picked.headerAt+1).map(row=>({number:String(row[idx.number]??"").trim(),classBranch:normalizeClassBranch(row[idx.classBranch]),name:String(row[idx.name]??"").replace(/\s+/g," ").trim(),gender:idx.gender<0?"":String(row[idx.gender]??"").trim(),diagnoses:splitDiagnoses(row[idx.diagnoses]),services:splitDiagnoses(row[idx.service])})).filter(x=>x.name&&x.classBranch&&!/^\d{1,2}[./-]\d{1,2}[./-]\d{4}$/.test(x.name));const grouped=new Map();raw.forEach(x=>{const key=rosterKey(x);if(!grouped.has(key))grouped.set(key,Object.assign({},x,{diagnoses:[],services:[]}));const item=grouped.get(key);item.diagnoses=[...new Set([...item.diagnoses,...x.diagnoses])];item.services=[...new Set([...item.services,...x.services])];if(!item.gender)item.gender=x.gender});return {fileName:file.name,sheetName:picked.sheetName,rawCount:raw.length,source:[...grouped.values()]}}
async function prepareStudentImport(file){try{const parsed=await parseStudentRoster(file),old=records.filter(x=>x.academicYear===school.year),oldMap=new Map(old.map(x=>[rosterKey(x),x])),newMap=new Map(parsed.source.map(x=>[rosterKey(x),x])),oldNotNew=old.filter(x=>!newMap.has(rosterKey(x))).map(x=>({id:x.id,number:x.student.number,name:x.student.name,classBranch:x.student.classBranch,diagnoses:arr(x.student.diagnoses)})),newNotOld=parsed.source.filter(x=>!oldMap.has(rosterKey(x))),diagnosisChanged=parsed.source.filter(x=>oldMap.has(rosterKey(x))&&!sameSet(oldMap.get(rosterKey(x)).student.diagnoses,x.diagnoses)).map(x=>{const previous=arr(oldMap.get(rosterKey(x)).student.diagnoses),current=arr(x.diagnoses);return {id:oldMap.get(rosterKey(x)).id,number:x.number,name:x.name,classBranch:x.classBranch,previous,current,added:current.filter(v=>!previous.includes(v)),removed:previous.filter(v=>!current.includes(v))}});pendingStudentImport=Object.assign(parsed,{createdAt:new Date().toISOString(),oldCount:old.length,oldNotNew,newNotOld,diagnosisChanged});page="importReview";render();scrollTo(0,0)}catch(error){alert("Öğrenci listesi karşılaştırılamadı.\n"+error.message)}}
async function saveImportArchive(applied){if(!pendingStudentImport)return null;const archive={id:uid(),createdAt:new Date().toISOString(),fileName:pendingStudentImport.fileName,sheetName:pendingStudentImport.sheetName,academicYear:school.year,applied:Boolean(applied),oldCount:pendingStudentImport.oldCount,newCount:pendingStudentImport.source.length,rawCount:pendingStudentImport.rawCount,oldNotNew:clone(pendingStudentImport.oldNotNew),newNotOld:clone(pendingStudentImport.newNotOld),diagnosisChanged:clone(pendingStudentImport.diagnosisChanged)};importArchives=[archive,...importArchives];await req(tx(SETTINGS,"readwrite").put({key:"importArchives",value:importArchives}));return archive}
async function applyPreparedStudentImport(){if(!pendingStudentImport)return;const source=pendingStudentImport.source,existing=new Map(records.filter(x=>x.academicYear===school.year).map(x=>[rosterKey(x),x])),classNames=[...new Set(source.map(x=>x.classBranch).filter(Boolean))],knownClasses=new Set((school.classes||[]).map(x=>importKey(x.name)));classNames.filter(x=>!knownClasses.has(importKey(x))).forEach(name=>school.classes.push({name,teacher:"",level:inferredClassLevel(name),schedule:""}));source.flatMap(x=>x.diagnoses).forEach(x=>{if(!school.disabilityOptions.some(v=>importKey(v)===importKey(x)))school.disabilityOptions.push(x)});await saveSchool();let sequence=await nextSequence();for(const x of source){const stored=existing.get(rosterKey(x)),item=stored?normalizeRecord(clone(stored)):emptyRecord(),now=new Date().toISOString(),classInfo=school.classes.find(c=>importKey(c.name)===importKey(x.classBranch));if(!stored){item.id=uid();item.sequence=sequence++;item.academicYear=school.year;item.createdAt=now;item.meeting.planDay="";item.meeting.time=""}item.updatedAt=now;item.student.number=x.number||item.student.number;item.student.classBranch=x.classBranch;item.student.name=x.name;item.student.gender=normalizeGender(x.gender)||item.student.gender;item.student.teacher=classInfo?.teacher||item.student.teacher||"";item.student.diagnoses=[...new Set(x.diagnoses)];if(x.services.length)item.student.recommendedService=x.services.join(" / ");item.committee.chair=item.committee.chair||(school.assistantPrincipals||[]).find(Boolean)||school.principal||"";item.committee.principal=school.principal||item.committee.principal||"";await req(tx(STORE,"readwrite").put(item))}await saveImportArchive(true);const summary={newCount:pendingStudentImport.newNotOld.length,changedCount:pendingStudentImport.diagnosisChanged.length,missingCount:pendingStudentImport.oldNotNew.length};pendingStudentImport=null;await loadAll();page="students";render();alert("Liste güncellendi ve karşılaştırma arşivlendi.\n\n"+summary.newCount+" yeni öğrenci eklendi.\n"+summary.changedCount+" öğrencinin engel türü güncellendi.\n"+summary.missingCount+" eski öğrenci yeni listede bulunmadı; kayıtları silinmedi.")}
function importList(items,type){if(!items.length)return "<p class='comparison-empty'>Bu kategoride öğrenci yok.</p>";return "<div class='comparison-list'>"+items.map(x=>"<div class='comparison-row'><div><strong>"+esc(x.name)+"</strong><small>"+esc([x.number,x.classBranch].filter(Boolean).join(" · "))+"</small></div>"+(type==="changed"?"<div class='diagnosis-change'><span><b>Önce:</b> "+esc(x.previous.join(", ")||"Yok")+"</span><span><b>Yeni:</b> "+esc(x.current.join(", ")||"Yok")+"</span>"+(x.added.length?"<em class='added'>Eklenen: "+esc(x.added.join(", "))+"</em>":"")+(x.removed.length?"<em class='removed'>Çıkan: "+esc(x.removed.join(", "))+"</em>":"")+"</div>":"<span>"+esc(arr(x.diagnoses).join(", ")||"Engel türü yok")+"</span>")+"</div>").join("")+"</div>"}
function importReviewPage(){if(!pendingStudentImport){page="students";return studentsPage()}const x=pendingStudentImport;return "<section class='hero'><div><h2>Excel öğrenci listesi karşılaştırması</h2><p>Henüz hiçbir kayıt değiştirilmedi. Sonuçları inceleyip güncellemeyi uygulayın.</p></div><button id='cancelStudentImport' class='light'>Karşılaştırmayı kapat</button></section><div class='comparison-summary'><div><strong>"+x.oldCount+"</strong><span>Eski liste</span></div><div><strong>"+x.source.length+"</strong><span>Yeni liste</span></div><div class='new'><strong>"+x.newNotOld.length+"</strong><span>Yeni öğrenci</span></div><div class='missing'><strong>"+x.oldNotNew.length+"</strong><span>Yeni listede yok</span></div><div class='changed'><strong>"+x.diagnosisChanged.length+"</strong><span>Engel türü değişti</span></div></div><article class='card comparison-card new'><div class='card-head'><div><h2>Yeni dosyada olup eski listede olmayanlar</h2><p>Güncelleme uygulandığında yeni öğrenci kaydı oluşturulur.</p></div></div><div class='card-body'>"+importList(x.newNotOld,"new")+"</div></article><article class='card comparison-card missing'><div class='card-head'><div><h2>Eski listede olup yeni dosyada olmayanlar</h2><p>Bilgi amaçlı gösterilir; mevcut kayıtlar otomatik silinmez.</p></div></div><div class='card-body'>"+importList(x.oldNotNew,"missing")+"</div></article><article class='card comparison-card changed'><div class='card-head'><div><h2>Engel türü değişen öğrenciler</h2><p>Eklenen ve listeden çıkan engel türleri ayrı gösterilir.</p></div></div><div class='card-body'>"+importList(x.diagnosisChanged,"changed")+"</div></article><div class='comparison-actions'><button id='archiveImportOnly' class='light'>Karşılaştırmayı arşivle</button><button id='applyStudentImport' class='primary'>Güncellemeleri uygula ve arşivle</button></div>"+footer()}
function importArchivesPage(){const cards=importArchives.map(a=>"<article class='card archive-card'><div><strong>"+esc(new Date(a.createdAt).toLocaleString("tr-TR"))+"</strong><span>"+esc(a.fileName)+" · "+esc(a.academicYear)+"</span></div><div><b>"+a.newNotOld.length+"</b> yeni öğrenci <b>"+a.oldNotNew.length+"</b> listede olmayan <b>"+a.diagnosisChanged.length+"</b> engel türü değişikliği</div><span class='archive-status "+(a.applied?"applied":"saved")+"'>"+(a.applied?"Güncelleme uygulandı":"Yalnızca arşivlendi")+"</span><button data-download-archive='"+a.id+"'>JSON indir</button></article>").join("");return "<section class='hero'><div><h2>Öğrenci listesi karşılaştırma arşivi</h2><p>Önceki Excel yüklemelerinde belirlenen farklar tarih ve dosya adıyla saklanır.</p></div><button data-page='students' class='light'>Öğrenci veritabanına dön</button></section><div class='archive-list'>"+(cards||"<article class='card'><div class='card-body empty-inline'>Henüz karşılaştırma arşivi bulunmuyor.</div></article>")+"</div>"+footer()}
