importArchivesPage=function(){const cards=importArchives.map(a=>"<details class='card archive-card archive-expand'><summary><div><strong>"+esc(new Date(a.createdAt).toLocaleString("tr-TR"))+"</strong><span>"+esc(a.fileName)+" · "+esc(a.academicYear)+"</span></div><div><b>"+a.newNotOld.length+"</b> yeni · <b>"+a.oldNotNew.length+"</b> listede yok · <b>"+a.diagnosisChanged.length+"</b> engel değişikliği</div><span class='archive-status "+(a.applied?"applied":"saved")+"'>"+(a.applied?"Uygulandı":"Arşivlendi")+"</span></summary><div class='archive-expanded'><h3>Yeni öğrenciler</h3>"+archiveStudentRows(a.newNotOld,"new")+"<h3>Yeni listede olmayan öğrenciler</h3>"+archiveStudentRows(a.oldNotNew,"missing")+"<h3>Engel türü değişen öğrenciler</h3>"+archiveStudentRows(a.diagnosisChanged,"changed")+"<h3>Okul bilgilerinde bulunmadığı için eklenmeyenler</h3>"+archiveStudentRows(a.unknownDiagnoses,"unknown")+"<button data-download-archive='"+a.id+"'>JSON indir</button></div></details>").join("");return "<section class='hero'><div><h2>Öğrenci listesi karşılaştırma arşivi</h2><p>Bir yüklemeye tıklayarak o tarihte hangi öğrencide ne değiştiğini görebilirsiniz.</p></div><button data-page='students' class='light'>Öğrenci veritabanına dön</button></section><div class='archive-list'>"+(cards||"<article class='card'><div class='card-body empty-inline'>Henüz karşılaştırma arşivi bulunmuyor.</div></article>")+"</div>"+footer()};
