function goalRowsFromGrid(grid,sheetName,fileName){const headerAt=grid.findIndex((row,i)=>i<20&&GOAL_HEADERS.every(h=>row.map(importKey).includes(h)));if(headerAt<0)return[];const headers=grid[headerAt].map(importKey),at=h=>headers.indexOf(h);return grid.slice(headerAt+1).map(row=>({ageGroup:String(row[at("sinifyasgrubu")]??"").trim(),course:String(row[at("dersalan")]??"").trim(),skillArea:String(row[at("becerialani")]??"").trim(),longTerm:String(row[at("uzundonemliamac")]??"").trim(),shortTerm:String(row[at("kisadonemliamac")]??"").trim(),step:String(row[at("basamak")]??"").trim(),sheet:sheetName,source:fileName})).filter(x=>x.ageGroup&&x.course&&x.skillArea&&x.longTerm&&x.shortTerm&&importKey(x.ageGroup)!=="sinif")}
async function prepareGoalImport(file){try{const sheets=[];if(/\.txt$/i.test(file.name)){const text=await file.text(),lines=text.replace(/^\uFEFF/,"").split(/\r?\n/).filter(Boolean),delimiter=(lines[0].match(/\t/g)||[]).length?"\t":((lines[0].match(/;/g)||[]).length>=(lines[0].match(/,/g)||[]).length?";":","),grid=lines.map(line=>line.split(delimiter).map(x=>x.trim().replace(/^"|"$/g,""))),rows=goalRowsFromGrid(grid,"Metin dosyası",file.name);if(rows.length)sheets.push({name:"Metin dosyası",rows,selected:true})}else{if(!globalThis.XLSX)throw new Error("Excel okuma bileşeni yüklenemedi.");const wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true});for(const name of wb.SheetNames){const grid=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:"",raw:false}),rows=goalRowsFromGrid(grid,name,file.name);if(rows.length)sheets.push({name,rows,selected:true})}}if(!sheets.length)throw new Error("Beklenen altı başlıkla amaç kaydı bulunamadı.");pendingGoalImport={fileName:file.name,sheets};page="goalImport";render();scrollTo(0,0)}catch(error){alert("Amaç havuzu okunamadı.\n"+error.message)}}
 async function applyGoalImport(){if(!pendingGoalImport)return;const selected=pendingGoalImport.sheets.filter((_,i)=>document.querySelector("[data-goal-sheet='"+i+"']")?.checked),rows=selected.flatMap(x=>x.rows);if(!rows.length){alert("En az bir sayfa seçin.");return}const key=x=>[x.ageGroup,x.course,x.skillArea,x.longTerm,x.shortTerm,x.step].map(importKey).join("|"),target=pendingGoalScope==="personal"?personalGoalLibrary:globalGoalLibrary,map=new Map(target.map(x=>[key(x),x]));rows.forEach(x=>map.set(key(x),Object.assign({},x,{scope:pendingGoalScope})));if(pendingGoalScope==="personal")personalGoalLibrary=[...map.values()];else globalGoalLibrary=[...map.values()];await req(tx(SETTINGS,"readwrite").put({key:pendingGoalScope==="personal"?"personalGoalLibrary":"globalGoalLibrary",value:[...map.values()]}));goalLibrary=[...globalGoalLibrary,...personalGoalLibrary];rows.map(x=>x.course).filter(Boolean).forEach(x=>{if(!school.courses.some(c=>importKey(c)===importKey(x)))school.courses.push(x)});school.courses.sort((a,b)=>a.localeCompare(b,"tr"));await saveSchool();pendingGoalImport=null;page="school";render();toast(rows.length+" amaç satırı işlendi")}
