function localDateKey(d){return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function agendaClassCompare(a,b){return String(a.student.classBranch||"").localeCompare(String(b.student.classBranch||""),"tr",{numeric:true,sensitivity:"base"})||(Number(a.sequence)||0)-(Number(b.sequence)||0)||String(a.student.name||"").localeCompare(String(b.student.name||""),"tr")}
function appointmentPlace(x){return x.meeting?.place||"PDR Servisi"}
function appointmentPassed(x){if(!x.meeting?.planDay||!x.meeting?.time)return false;const t=new Date(x.meeting.planDay+"T"+x.meeting.time+":00").getTime();return Number.isFinite(t)&&t<=Date.now()}
function attendedMeetingNumbers(x){const attendance=x.family?.meetingAttendance||{};return [0,1,2].filter(i=>["mother","father","guardian"].some(k=>Boolean(attendance[k]?.[i]))).map(i=>i+1)}
function meetingParticipationText(x){const meetings=attendedMeetingNumbers(x);if(meetings.length===3)return "Tümüne Katıldı";if(meetings.length===2)return meetings[0]+". ve "+meetings[1]+". Toplantılara Katıldı";if(meetings.length===1)return meetings[0]+". Toplantıya Katıldı";return "Veli Katılmadı"}
function agendaAttendance(x){const joined=attendedMeetingNumbers(x).length>0;if(joined)return {text:meetingParticipationText(x),className:"agenda-attended"};if(appointmentPassed(x))return {text:"Veli Katılmadı",className:"agenda-absent"};return {text:"Bekleniyor",className:"agenda-waiting"}}
function weekdayName(value){if(!value)return "";return new Date(value+"T12:00:00").toLocaleDateString("tr-TR",{weekday:"long"})}
function agendaPage(){const year=agendaMonth.getFullYear(),month=agendaMonth.getMonth(),title=agendaMonth.toLocaleDateString("tr-TR",{month:"long",year:"numeric"}),firstOffset=(new Date(year,month,1).getDay()+6)%7,lastDay=new Date(year,month+1,0).getDate(),allowed=records.filter(x=>!isRamClassMismatch(x)).sort(agendaClassCompare),locked=records.filter(isRamClassMismatch),events=new Map();allowed.forEach(x=>{const key=x.meeting?.planDay;if(key){if(!events.has(key))events.set(key,[]);events.get(key).push(x)}});events.forEach(items=>items.sort((a,b)=>String(a.meeting?.time||"").localeCompare(String(b.meeting?.time||""))||agendaClassCompare(a,b)));const cells=[...Array.from({length:firstOffset},()=>"<div class='calendar-cell outside'></div>"),...Array.from({length:lastDay},(_,i)=>{const day=i+1,key=localDateKey(new Date(year,month,day)),items=events.get(key)||[];return "<div class='calendar-cell "+(key===today()?"today":"")+" "+(key===agendaSelectedDate?"selected-day":"")+"' data-agenda-day='"+key+"' title='Bu güne randevu eklemek için tıklayın'><strong>"+day+"</strong><div class='calendar-events'>"+items.map(x=>"<button data-open='"+x.id+"'><span>"+esc(x.meeting.time||"Saat yok")+"</span>"+esc(x.student.name)+"<small>"+esc(x.student.classBranch)+"</small></button>").join("")+"</div><small class='day-add'>+ Randevu ekle</small></div>"})].join("");const sorted=records.slice().sort((a,b)=>Number(isRamClassMismatch(a))-Number(isRamClassMismatch(b))||agendaClassCompare(a,b));const rows=sorted.map(x=>{const blocked=isRamClassMismatch(x),status=agendaAttendance(x),place=appointmentPlace(x);return "<tr class='"+(blocked?"agenda-locked":status.className)+"'><td><strong>"+esc(x.student.name)+"</strong></td><td>"+esc(x.student.classBranch)+"</td><td>"+esc(x.student.teacher)+"</td><td>"+(blocked?"<span class='lock-badge'>Planlamaya kapalı</span>":"<input type='date' data-agenda-date='"+x.id+"' value='"+esc(x.meeting?.planDay||"")+"'>")+"</td><td>"+(blocked?"—":"<input type='time' data-agenda-time='"+x.id+"' value='"+esc(x.meeting?.time||"")+"'>")+"</td><td>"+(blocked?"RAM sınıf kademesi uyumsuzluğu":"<select data-agenda-place='"+x.id+"'>"+MEETING_PLACES.map(v=>"<option "+(place===v?"selected":"")+" value='"+esc(v)+"'>"+esc(v)+"</option>").join("")+"</select>")+"</td><td>"+(blocked?"—":"<strong class='attendance-badge'>"+status.text+"</strong>")+"</td></tr>"}).join("");const selectedLabel=agendaSelectedDate?d(agendaSelectedDate)+" "+weekdayName(agendaSelectedDate):"";const planner=agendaSelectedDate?"<article class='card agenda-day-planner'><div class='card-head'><div><h2>"+esc(selectedLabel)+" için randevu planla</h2><p>Öğrenciyi seçip saat ve yeri belirleyin. Toplantı yeri varsayılan olarak PDR Servisi'dir.</p></div><button id='closeAgendaPlanner' class='light'>Kapat</button></div><div class='card-body planner-grid'><label><span>Öğrenci</span><select id='agendaDayStudent'><option value=''>Öğrenci seçin</option>"+allowed.map(x=>"<option value='"+x.id+"'>"+esc(x.student.classBranch+" · "+x.student.name)+"</option>").join("")+"</select></label><label><span>Toplantı saati</span><input id='agendaDayTime' type='time'></label><label><span>Toplantı yeri</span><select id='agendaDayPlace'>"+MEETING_PLACES.map(v=>"<option "+(v==="PDR Servisi"?"selected":"")+" value='"+esc(v)+"'>"+esc(v)+"</option>").join("")+"</select></label><button id='saveAgendaDay' class='primary'>Randevuyu kaydet</button></div></article>":"";const scheduled=allowed.filter(x=>x.meeting?.planDay).slice().sort((a,b)=>String(a.meeting.planDay).localeCompare(String(b.meeting.planDay))||String(a.meeting.time||"").localeCompare(String(b.meeting.time||""))||agendaClassCompare(a,b));const printRows=scheduled.map((x,i)=>{const status=agendaAttendance(x);return "<tr class='"+status.className+"'><td>"+(i+1)+"</td><td>"+esc(d(x.meeting.planDay))+"<br>"+esc(weekdayName(x.meeting.planDay))+"</td><td>"+esc(x.meeting.time||"—")+"</td><td>"+esc(x.student.classBranch)+"</td><td>"+esc(x.student.name)+"</td><td>"+esc(x.student.teacher)+"</td><td>"+esc(appointmentPlace(x))+"</td><td>"+status.text+"</td></tr>"}).join("");return "<section class='hero agenda-hero'><div><h2>BEP toplantı ajandası</h2><p>Takvimde bir güne tıklayarak veya sınıf sıralı öğrenci listesinden toplantı planlayın.</p></div><div><strong>"+allowed.length+" planlanabilir</strong><span>"+locked.length+" RAM uyarılı kayıt kilitli</span></div></section><article class='card agenda-calendar-card'><div class='card-head agenda-head'><button data-agenda-shift='-1'>← Önceki ay</button><h2>"+esc(title)+"</h2><button data-agenda-shift='1'>Sonraki ay →</button></div><div class='card-body'><div class='calendar-weekdays'>"+["Pzt","Sal","Çar","Per","Cum","Cmt","Paz"].map(x=>"<span>"+x+"</span>").join("")+"</div><div class='agenda-calendar'>"+cells+"</div></div></article>"+planner+"<article class='card agenda-screen-list'><div class='card-head'><div><h2>Öğrenci toplantı planları</h2><p>Öğrenciler sınıf adına göre sıralanır. RAM uyumsuzluğu bulunan öğrenciler için randevu girilemez.</p></div><div class='agenda-list-actions'><button id='printAgendaList'>Sıralı listeyi yazdır</button><button id='clearAgendaAppointments' class='danger'>Tüm toplantı randevu tarihlerini sil</button></div></div><div class='output-wrap'><table class='db-table agenda-table'><thead><tr><th>Öğrenci</th><th>Sınıf</th><th>Sınıf öğretmeni</th><th>Tarih</th><th>Saat</th><th>Toplantı yeri / durum</th><th>Veli katılımı</th></tr></thead><tbody>"+(rows||"<tr><td colspan='7' class='empty'>Kayıtlı öğrenci bulunamadı.</td></tr>")+"</tbody></table></div></article><article class='agenda-print-list'><h1>BEP Toplantı Ajandası — Sıralı Liste</h1><p>"+esc(school.name)+" · "+esc(school.year)+"</p><table><thead><tr><th>Sıra</th><th>Tarih / Gün</th><th>Saat</th><th>Sınıf</th><th>Öğrenci</th><th>Sınıf öğretmeni</th><th>Toplantı yeri</th><th>Veli katılımı</th></tr></thead><tbody>"+(printRows||"<tr><td colspan='8'>Planlanmış toplantı bulunmamaktadır.</td></tr>")+"</tbody></table></article>"+footer()}
async function clearAgendaAppointments(){const planned=records.filter(x=>x.meeting?.planDay||x.meeting?.time);if(!planned.length){alert("Silinecek planlanmış toplantı randevusu bulunamadı.");return}const password=prompt("Tüm toplantı tarih ve saatlerini silmek için şifreyi girin:");if(password===null)return;if(password!=="0000"){alert("Şifre yanlış. Hiçbir randevu silinmedi.");return}if(!confirm(planned.length+" öğrenciye ait toplantı tarih ve saatleri silinecek. Devam edilsin mi?"))return;for(const source of planned){const x=normalizeRecord(clone(source));x.meeting.planDay="";x.meeting.time="";x.updatedAt=new Date().toISOString();await req(tx(STORE,"readwrite").put(x))}if(record.id&&planned.some(x=>x.id===record.id)){record.meeting.planDay="";record.meeting.time=""}await loadAll();render();alert("Tüm toplantı randevu tarihleri ve saatleri silindi. Yeni toplantı takvimini yeniden planlayabilirsiniz.")}
function familyContact(x){return x.family.guardianName||x.family.motherName||x.family.fatherName||"Veli"}
function appointmentText(x,audience){const date=x.meeting?.planDay?d(x.meeting.planDay):"Belirlenmedi",day=x.meeting?.planDay?weekdayName(x.meeting.planDay):"Belirlenmedi",time=x.meeting?.time||"Belirlenmedi",place=appointmentPlace(x),name=x.student.name,courses=[...new Set((x.performance||[]).map(p=>String(p.area||"").trim()).filter(Boolean))],courseText=courses.length?courses.join(", ")+" derslerine":"öğrencinin BEP hazırlanacak derslerine";const details="Toplantı tarihi: "+date+" ("+day+"). Toplantı saati: "+time+". Toplantı yeri: "+place+".";if(audience==="teacher")return "Sayın "+(x.student.teacher||"Öğretmenimiz")+", "+name+" isimli öğrencimizin BEP toplantısı planlanmıştır. "+details+" Toplantıya gelirken "+courseText+" ilişkin öğrencinin eğitsel performansını, uzun dönemli amaçlarını ve kısa dönemli amaçlarını hazır olarak getirmenizi rica ederiz. Katılımınızı rica ederiz. "+school.name;return "Sayın "+familyContact(x)+", öğrenciniz "+name+" için BEP toplantısı planlanmıştır. "+details+" Katılımınızı rica ederiz. "+school.name}
