function identityPage(){const service=selectField("Önerilen hizmet","student.recommendedService",SERVICE_OPTIONS,"full"),all=school.disabilityOptions||[];const diagnoses="<div class='field full'><label>Engel durumu (birden fazla seçilebilir)</label><div class='choice-grid'>"+all.map((x,i)=>"<div class='check option-check'><label><input type='checkbox' data-diagnosis='"+esc(x)+"' "+(record.student.diagnoses.includes(x)?"checked":"")+"><span>"+esc(x)+"</span></label><button data-edit-diagnosis='"+i+"' title='Değiştir'>Düzenle</button><button data-delete-diagnosis='"+i+"' class='danger' title='Sil'>Sil</button></div>").join("")+"</div><div class='inline-add'><input id='newDiagnosis' placeholder='Yeni engel durumu ekle'><button id='addDiagnosis'>Listeye ekle</button></div></div>";return recordHero()+cardClass("Kimlik, sınıf ve nüfus bilgileri",field("Otomatik sıra","sequence","number","id-sequence","Program tarafından verilir")+field("Okul No","student.number","text","id-school-no")+tcField()+selectField("Sınıfı / şubesi","student.classBranch",(school.classes||[]).map(x=>x.name),"id-class")+field("Adı soyadı","student.name","text","id-name")+field("Öğretmeni","student.teacher","text","id-teacher","Seçilen sınıfın öğretmeni otomatik gelir")+selectField("Cinsiyeti","student.gender",["Erkek","Kız"],"id-gender")+field("Doğum tarihi","student.birthDate","date","id-birth")+selectField("Grup","student.group",GROUP_OPTIONS,"id-group")+field("BEP başlangıç tarihi","student.bepStart","date","id-date","Yeni kayıtta bugünün tarihi")+field("BEP bitiş tarihi","student.bepEnd","date","id-date","Varsayılan tarih değiştirilebilir")+field("Eğitim ve öğretim yılı","academicYear","text","id-year")+service+diagnoses,"identity-card")+cardClass("Aile bilgileri",familyFields(),"family-card")+saveBar()+footer()}
function familyAttendance(){record.family.meetingAttendance=record.family.meetingAttendance||{mother:[false,false,false],father:[false,false,false],guardian:[false,false,false]};["mother","father","guardian"].forEach(k=>record.family.meetingAttendance[k]=Array.from({length:3},(_,i)=>Boolean(record.family.meetingAttendance[k]?.[i])));return record.family.meetingAttendance}
function familyAttendanceFields(){const a=familyAttendance(),people=[["mother","Anne",record.family.motherName],["father","Baba",record.family.fatherName],...(record.family.guardianIsOther?[["guardian","Vasi / diğer yakını",record.family.guardianName]]:[])];return "<div class='field full family-attendance'><div class='attendance-title'><strong>BEP toplantısına katılan aile üyesi</strong><small>Katıldığı toplantıların kutularını işaretleyin. İşaretlenen kişiler 5. sayfaya otomatik aktarılır.</small></div><div class='attendance-table'><div class='attendance-head'><span>Yakınlığı ve adı</span><span>1. toplantı</span><span>2. toplantı</span><span>3. toplantı</span></div>"+people.map(p=>"<div class='attendance-row'><strong>"+p[1]+(p[2]?" — "+esc(p[2]):"")+"</strong>"+[0,1,2].map(i=>"<label><input type='checkbox' data-family-attendance='"+p[0]+"' data-meeting='"+i+"' "+(a[p[0]][i]?"checked":"")+"><span>Katıldı</span></label>").join("")+"</div>").join("")+"</div></div>"}
function familyPersonFields(key,label){const works=Boolean(record.family[key+"Works"]);return "<section class='family-person family-parent'><div class='family-person-head'><h3>"+label+" bilgileri</h3><label class='check work-check'><input type='checkbox' data-family-work='"+key+"' "+(works?"checked":"")+"><span>İşte Çalışıyor</span></label></div><div class='family-person-grid'>"+field("Adı soyadı","family."+key+"Name","text","family-half")+field("Telefonu","family."+key+"Phone","text","family-half")+field("Ev adresi","family."+key+"Home","textarea","family-full")+(works?field("İş telefonu","family."+key+"WorkPhone","text","family-half")+field("İş adresi","family."+key+"Work","textarea","family-full"):"")+"</div></section>"}
function familyFields(){const guardian="<div class='field full guardian-toggle'><label class='check'><input id='guardianOther' type='checkbox' "+(record.family.guardianIsOther?"checked":"")+"><span>Veli / vasi anne veya babadan başka biri</span></label></div>"+(record.family.guardianIsOther?"<section class='family-person family-guardian'><div class='family-person-head'><h3>Veli / vasi bilgileri</h3></div><div class='family-person-grid'>"+field("Adı soyadı","family.guardianName","text","family-half")+field("Telefonu","family.guardianPhone","text","family-half")+field("Ev adresi","family.guardianHome","textarea","family-full")+field("İş adresi","family.guardianWork","textarea","family-full")+"</div></section>":"");return familyPersonFields("mother","Anne")+familyPersonFields("father","Baba")+guardian+familyAttendanceFields()}
function recordHero(){const q=importKey(recordPickerQuery),available=records.filter(x=>!q||importKey([x.student.name,x.student.classBranch,x.student.number].join(" ")).includes(q)).sort((a,b)=>String(a.student.classBranch||"").localeCompare(String(b.student.classBranch||""),"tr",{numeric:true})||String(a.student.name||"").localeCompare(String(b.student.name||""),"tr")),permission=activeTeacher?(page==="performance"||page==="plan"?"Bu öğrencinin bu sayfadaki BEP verilerini görüntüleyebilir ve değiştirebilirsiniz.":"Sarı alanları değiştirebilir; kırmızı alanları yalnızca görüntüleyebilirsiniz."):"Yönetici olarak öğrencinin tüm kayıtlarına erişebilirsiniz.";return "<section class='student-access-bar'><div><strong>Öğrenci seçimi</strong><span>"+esc(permission)+"</span></div><input id='recordPickerFilter' value='"+esc(recordPickerQuery)+"' placeholder='Ad, sınıf veya okul no ile filtrele'><select id='recordPicker'><option value=''>Öğrenci seçin</option>"+available.map(x=>"<option value='"+x.id+"' "+(x.id===record.id?"selected":"")+">"+esc(x.student.classBranch+" · "+x.student.name+(x.student.number?" · "+x.student.number:""))+"</option>").join("")+"</select></section><section class='record-strip student-summary'><div><span>Öğrenci</span><strong>"+esc(record.student.name||"Yeni öğrenci")+"</strong></div><div><span>Sınıfı</span><strong>"+esc(record.student.classBranch||"-")+"</strong></div><div><span>Sınıf öğretmeni</span><strong>"+esc(record.student.teacher||classTeacherName()||"-")+"</strong></div><div><span>Grup</span><strong>"+esc(record.student.group||"-")+"</strong></div></section>"}
