function performancePage(){const row=(x,i)=>"<section class='dynamic-row performance-guided'><div class='dynamic-row-head'><strong>Gelişim alanı / ders "+(i+1)+"</strong>"+(record.performance.length>1?"<button data-remove-performance='"+i+"' class='danger'>Satırı kaldır</button>":"")+"</div><div class='grid'>"+courseField("Ders / gelişim alanı","performance."+i+".area","full")+performanceGoalPicker(x,i)+field("Ek açıklama / elle performans girişi","performance."+i+".level","textarea","full")+"</div></section>",rows=record.performance.map(row).join("");return recordHero()+card("Geçmiş, sağlık ve düzenlemeler",field("Daha önce aldığı destek hizmetleri ve süresi","student.previousSupport","textarea","half")+field("Almakta olduğu okul dışı destek hizmetleri ve süresi","student.currentSupport","textarea","half")+field("Destek materyalleri / cihazlar","student.devices","textarea","half")+field("Önemli sağlık bilgileri","student.health","textarea","half")+field("Eğitim ortamına ilişkin düzenlemeler","student.environment","textarea","full"))+card("Eğitsel performans","<div class='goal-guidance full'><strong>Öğrencinin yapabildiklerini seçin.</strong><span>Ders, beceri alanı ve amaçlar sırayla açılır. Her işaretlenen kazanımın düzeyini yüzde olarak belirleyin.</span></div>"+field("Öğrencinin gelişim öyküsü","student.developmentStory","textarea","full")+rows+"<div class='performance-add'><button id='addPerformance'>+ Gelişim alanı / ders ekle</button></div>"+field("Varsa davranış problemi","student.behaviorProblem","textarea","full"))+saveBar()+footer()}
