function planGuidedPicker(p,pool){const performanceSkills=record.performance.filter(x=>x.area===activePlanCourse).flatMap(x=>arr(x.skillAreas?.length?x.skillAreas:x.skillArea)),skills=[...new Set([...performanceSkills,...pool.map(x=>x.skillArea)])],selectedSkills=arr(p.draftSkills),selectedLongs=arr(p.draftLongTerms);let html="<div class='plan-guide full'><fieldset class='wide-choice-list compact-choice'><legend>1. Beceri alanlarını seçin (birden fazla seçilebilir)</legend>"+skills.map(x=>"<label class='"+(performanceSkills.includes(x)?"from-performance":"")+"'><input type='checkbox' data-plan-skill value='"+esc(x)+"' "+(selectedSkills.includes(x)?"checked":"")+"><span>"+esc(x)+(performanceSkills.includes(x)?" <small>Eğitsel performansta seçildi</small>":"")+"</span></label>").join("")+"</fieldset>";if(selectedSkills.length)html+=selectedSkills.map(skill=>{const rows=pool.filter(x=>x.skillArea===skill),longs=[...new Set(rows.map(x=>x.longTerm))];return "<section class='skill-goal-section'><h4>"+esc(skill)+"</h4><fieldset class='wide-choice-list compact-choice long-list'><legend>2. Uzun dönemli amaçları seçin</legend>"+longs.map(long=>{const key=skill+"|"+long;return "<label><input type='checkbox' data-plan-long value='"+esc(key)+"' "+(selectedLongs.includes(key)?"checked":"")+"><span>"+esc(long)+"</span></label>"}).join("")+"</fieldset>"+longs.filter(long=>selectedLongs.includes(skill+"|"+long)).map(long=>"<fieldset class='short-goal-bank compact-choice'><legend>3. Kısa dönemli amaçları seçin</legend>"+rows.filter(x=>x.longTerm===long).map(x=>{const key=[x.skillArea,x.longTerm,x.shortTerm,x.step].join("|"),checked=p.rows.some(r=>[r.skillArea,r.longTerm,r.shortTerm,r.step].join("|")===key);return "<label><input type='checkbox' data-plan-short-key='"+esc(key)+"' "+(checked?"checked":"")+"><span>"+esc(x.shortTerm)+(x.step?" <small>Basamak "+esc(x.step)+"</small>":"")+"</span></label>"}).join("")+"</fieldset>").join("")+"</section>"}).join("");html+="<details class='manual-plan-entry'><summary>Amaçları elle girmek istiyorum</summary><div class='manual-goal-entry'><input id='manualSkillGoal' placeholder='Beceri alanı'><textarea id='manualLongGoal' placeholder='Uzun dönemli amacı yazın'></textarea><textarea id='manualShortGoal' placeholder='Kısa dönemli amacı yazın'></textarea><button id='addManualGoal' class='primary'>Amacı ekle</button></div></details></div>";return html}
