function pdfSavePanel(){const classes=[...new Set(records.map(x=>x.student.classBranch).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"tr",{numeric:true,sensitivity:"base"}));if(!pdfSaveClass)pdfSaveClass=record.student.classBranch||classes[0]||"";const scoped=pdfSaveScope==="class"?records.filter(x=>x.student.classBranch===pdfSaveClass):records,excluded=pdfSaveScope==="current"?0:scoped.filter(isRamClassMismatch).length,eligible=pdfSaveScope==="current"?(record.student.name?1:0):scoped.length-excluded;return "<article class='card pdf-save-card'><div class='card-head'><div><h2>PDF dosyalarını bilgisayara kaydet</h2><p>Seçili çıktı sayfalarını açık öğrenci, bir sınıf veya tüm öğrenci kayıtları için tek PDF dosyası olarak indirin.</p></div></div><div class='card-body pdf-save-grid'><label><span>Kayıt kapsamı</span><select id='pdfSaveScope'><option value='current' "+(pdfSaveScope==="current"?"selected":"")+">Sayfası açık öğrenci (varsayılan)</option><option value='class' "+(pdfSaveScope==="class"?"selected":"")+">Bir sınıftaki öğrenciler</option><option value='all' "+(pdfSaveScope==="all"?"selected":"")+">Tüm öğrenciler</option></select></label>"+(pdfSaveScope==="class"?"<label><span>Kaydedilecek sınıf</span><select id='pdfSaveClass'>"+classes.map(x=>"<option value='"+esc(x)+"' "+(x===pdfSaveClass?"selected":"")+">"+esc(x)+"</option>").join("")+"</select></label>":"")+"<div class='pdf-save-summary'><strong>"+(pdfSaveScope==="current"?esc(record.student.name||"Öğrenci seçilmedi"):eligible+" BEP kaydı")+"</strong><small>Yukarıda işaretli "+selectedOutputs.length+" çıktı türü PDF'e eklenecek.</small>"+(excluded?"<em>"+excluded+" RAM uyumsuz öğrenci toplu PDF dışında bırakılacak.</em>":"")+"</div><button id='savePdfToComputer' class='primary' "+(pdfSaving?"disabled":"")+">"+(pdfSaving?"PDF hazırlanıyor...":"PDF olarak bilgisayara kaydet")+"</button><div id='pdfSaveProgress' class='pdf-save-progress' aria-live='polite'></div></div></article>"}
function previewsPage(){return recordHero()+"<article class='card'><div class='card-head'><div><h2>Toplu çıktı</h2><p>Tüm sayfaları veya seçtiğiniz sayfaları tek yazdırma işleminde PDF alın.</p></div><div class='bulk-actions'><button id='selectAllOutputs'>Tümünü seç</button><button id='printSelected' class='primary'>Seçilenleri yazdır</button></div></div><div class='card-body'><div class='preview-grid'>"+OUTPUTS.map(x=>"<div class='preview-card'><label class='output-check'><input type='checkbox' data-output='"+x[0]+"' "+(selectedOutputs.includes(x[0])?"checked":"")+"> Çıktıya ekle</label><strong>"+x[1]+"</strong><span>"+x[2]+"</span><button data-preview='"+x[0]+"'>Tek önizleme / PDF</button></div>").join("")+"</div></div></article>"+pdfSavePanel()+footer()}
