function paperFragment(key){if(key==="p7")return evaluationCourses().map((name,i)=>"<section class='batch-page landscape-page evaluation-paper'>"+evaluationBody(name,i)+"</section>").join("");if(key==="p3"){const courses=evaluationCourses();return courses.map((name,i)=>"<section class='batch-page landscape-page'>"+planCourseBody(name,i,courses.length)+"</section>").join("")}const old=page;page=key;const html={p1,p2,p4,p5,p6,kpk}[key]();page=old;const start=html.indexOf("<div class='paper "),open=html.indexOf(">",start)+1,end=html.lastIndexOf("</div></div></article>");return "<section class='batch-page "+(["p1","kpk"].includes(key)?"portrait-page":"landscape-page")+"'>"+html.slice(open,end)+"</section>"}
