 document.querySelectorAll("[data-add-option]").forEach(el=>el.onclick=()=>{const input=document.querySelector("[data-new-option='"+el.dataset.addOption+"']"),x=input.value.trim();if(x&&!school[el.dataset.addOption].includes(x))school[el.dataset.addOption].push(x);school[el.dataset.addOption].sort((a,b)=>a.localeCompare(b,"tr"));dirty=true;render()});
 document.querySelectorAll(".save-record").forEach(b=>b.onclick=()=>saveRecord());
