 document.querySelectorAll("[data-diagnosis]").forEach(el=>el.onchange=()=>{const x=el.dataset.diagnosis;record.student.diagnoses=el.checked?[...new Set([...record.student.diagnoses,x])]:record.student.diagnoses.filter(v=>v!==x);dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-edit-diagnosis]").forEach(el=>el.onclick=async()=>{const i=Number(el.dataset.editDiagnosis),old=school.disabilityOptions[i],x=prompt("Engel durumunu değiştirin:",old);if(!x||x.trim()===old)return;school.disabilityOptions[i]=x.trim();record.student.diagnoses=record.student.diagnoses.map(v=>v===old?x.trim():v);school.disabilityOptions.sort((a,b)=>a.localeCompare(b,"tr"));await saveSchool();dirty=true;render()});
 document.querySelectorAll("[data-delete-diagnosis]").forEach(el=>el.onclick=async()=>{const i=Number(el.dataset.deleteDiagnosis),old=school.disabilityOptions[i];if(!confirm("'"+old+"' seçeneği listeden silinsin mi?"))return;school.disabilityOptions.splice(i,1);record.student.diagnoses=record.student.diagnoses.filter(v=>v!==old);await saveSchool();dirty=true;render()});
 document.querySelectorAll("[data-family-attendance]").forEach(el=>el.onchange=()=>{const a=familyAttendance();a[el.dataset.familyAttendance][Number(el.dataset.meeting)]=el.checked;dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-family-work]").forEach(el=>el.onchange=()=>{record.family[el.dataset.familyWork+"Works"]=el.checked;dirty=true;render()});
 const addPerformance=document.querySelector("#addPerformance");if(addPerformance)addPerformance.onclick=()=>{record.performance.push({area:"",level:"",skillArea:"",achievements:[]});dirty=true;render()};
 document.querySelectorAll("[data-path^='performance.'][data-path$='.area']").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.path.split(".")[1]),p=record.performance[i];p.area=el.value;p.skillArea="";p.skillAreas=[];p.selectedLongTerms=[];p.achievements=[];dirty=true;render()});
 document.querySelectorAll("[data-performance-skill]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.performanceSkill),p=record.performance[i],scope="input[data-performance-skill='"+i+"']:checked";p.skillAreas=[...document.querySelectorAll(scope)].map(x=>x.value);p.skillArea=p.skillAreas.join(", ");p.selectedLongTerms=arr(p.selectedLongTerms).filter(x=>p.skillAreas.some(skill=>x.startsWith(skill+"|")));p.achievements=arr(p.achievements).filter(a=>p.skillAreas.includes(String(a.key||"").split("|")[0]));dirty=true;render()});
 document.querySelectorAll("[data-performance-long]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.performanceLong),p=record.performance[i],scope="input[data-performance-long='"+i+"']:checked";p.selectedLongTerms=[...document.querySelectorAll(scope)].map(x=>x.value);p.achievements=arr(p.achievements).filter(a=>p.selectedLongTerms.includes(String(a.key||"").split("|").slice(0,2).join("|")));dirty=true;render()});
 document.querySelectorAll("[data-performance-achievement]").forEach(el=>el.onchange=()=>{const p=record.performance[Number(el.dataset.performanceAchievement)],key=el.dataset.achievementKey;p.achievements=arr(p.achievements);if(el.checked&&!p.achievements.some(a=>a.key===key))p.achievements.push({key,percentage:"%100"});if(!el.checked)p.achievements=p.achievements.filter(a=>a.key!==key);dirty=true;render()});
 document.querySelectorAll("[data-performance-percent]").forEach(el=>el.onchange=()=>{const p=record.performance[Number(el.dataset.performancePercent)],a=arr(p.achievements).find(x=>x.key===el.dataset.achievementKey);if(a)a.percentage=el.value;dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-remove-performance]").forEach(el=>el.onclick=()=>{record.performance.splice(Number(el.dataset.removePerformance),1);if(!record.performance.length)record.performance.push({area:"",level:""});dirty=true;render()});
 const addDecision=document.querySelector("#addDecision");if(addDecision)addDecision.onclick=()=>{record.decisions.other.push("");dirty=true;render()};
 document.querySelectorAll("[data-remove-decision]").forEach(el=>el.onclick=()=>{record.decisions.other.splice(Number(el.dataset.removeDecision),1);if(!record.decisions.other.length)record.decisions.other.push("");dirty=true;render()});
 const guardian=document.querySelector("#guardianOther");if(guardian)guardian.onchange=()=>{record.family.guardianIsOther=guardian.checked;if(!guardian.checked){record.family.guardianName="";record.family.guardianPhone="";record.family.guardianHome="";record.family.guardianWork="";familyAttendance().guardian=[false,false,false]}dirty=true;render()};
