 document.querySelectorAll("[data-plan-skill]").forEach(el=>el.onchange=()=>{const p=record.plan.byCourse[activePlanCourse];p.draftSkills=[...document.querySelectorAll("[data-plan-skill]:checked")].map(x=>x.value);p.draftLongTerms=arr(p.draftLongTerms).filter(x=>p.draftSkills.some(skill=>x.startsWith(skill+"|")));dirty=true;render()});
 document.querySelectorAll("[data-plan-long]").forEach(el=>el.onchange=()=>{const p=record.plan.byCourse[activePlanCourse];p.draftLongTerms=[...document.querySelectorAll("[data-plan-long]:checked")].map(x=>x.value);dirty=true;render()});
 document.querySelectorAll("[data-plan-short-key]").forEach(el=>el.onchange=()=>{const p=record.plan.byCourse[activePlanCourse],matches=r=>[r.skillArea,r.longTerm,r.shortTerm,r.step].join("|")===el.dataset.planShortKey;if(el.checked&&!p.rows.some(matches)){const found=courseGoalPool(activePlanCourse).find(x=>[x.skillArea,x.longTerm,x.shortTerm,x.step].join("|")===el.dataset.planShortKey);if(found)p.rows.push(Object.assign(goalRow(),{skillArea:found.skillArea,longTerm:found.longTerm,shortTerm:found.shortTerm,step:found.step}))}else if(!el.checked)p.rows=p.rows.filter(r=>!matches(r));p.rows=p.rows.filter(r=>r.longTerm||r.shortTerm);dirty=true;render()});
 const addManualGoal=document.querySelector("#addManualGoal");if(addManualGoal)addManualGoal.onclick=()=>{const p=record.plan.byCourse[activePlanCourse],skill=document.querySelector("#manualSkillGoal").value.trim(),long=document.querySelector("#manualLongGoal").value.trim(),short=document.querySelector("#manualShortGoal").value.trim();if(!long){alert("Uzun dönemli amacı yazın.");return}p.rows=p.rows.filter(r=>r.longTerm||r.shortTerm);p.rows.push(Object.assign(goalRow(),{skillArea:skill,longTerm:long,shortTerm:short}));dirty=true;render()};
 document.querySelectorAll("[data-plan-next]").forEach(planNext=>planNext.onclick=()=>{const courses=performanceCourses(),i=courses.indexOf(activePlanCourse);if(i>=0&&i<courses.length-1){activePlanCourse=courses[i+1];render();scrollTo(0,0)}else{page="decisions";render();scrollTo(0,0)}});
 document.querySelectorAll("[data-plan-prev]").forEach(planPrev=>planPrev.onclick=()=>{const courses=performanceCourses(),i=courses.indexOf(activePlanCourse);if(i>0){activePlanCourse=courses[i-1];render();scrollTo(0,0)}else{page="performance";render();scrollTo(0,0)}});
 document.querySelectorAll("[data-plan-field]").forEach(el=>el.oninput=()=>{record.plan.byCourse[activePlanCourse].rows[Number(el.dataset.planIndex)][el.dataset.planField]=el.value;dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-goal-choice]").forEach(el=>el.onchange=()=>{if(!el.value)return;const i=Number(el.dataset.planIndex),r=record.plan.byCourse[activePlanCourse].rows[i],pool=courseGoalPool(activePlanCourse);if(el.dataset.goalChoice==="skill"){r.skillArea=el.value;r.longTerm="";r.shortTerm="";r.step=""}else if(el.dataset.goalChoice==="long"){r.longTerm=el.value;r.shortTerm="";r.step=""}else{const found=pool.find(x=>x.shortTerm===el.value&&(!r.skillArea||x.skillArea===r.skillArea)&&(!r.longTerm||x.longTerm===r.longTerm));r.shortTerm=el.value;if(found){r.skillArea=found.skillArea;r.longTerm=found.longTerm;r.step=found.step}}dirty=true;render()});
 document.querySelectorAll("[data-plan-methods]").forEach(el=>el.onchange=()=>{record.plan.byCourse[activePlanCourse].rows[Number(el.dataset.planMethods)].methods=[...el.selectedOptions].map(x=>x.value);dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-plan-array]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.planIndex),key=el.dataset.planArray,scope="input[data-plan-array='"+CSS.escape(key)+"'][data-plan-index='"+i+"']:checked";record.plan.byCourse[activePlanCourse].rows[i][key]=[...document.querySelectorAll(scope)].map(x=>x.value);dirty=true;state("Kaydedilmemiş değişiklik")});
 document.querySelectorAll("[data-plan-score]").forEach(el=>el.onchange=()=>{record.plan.byCourse[activePlanCourse].rows[Number(el.dataset.planScore)].status=el.value;dirty=true;render()});
 const env=document.querySelector("#courseEnvironment");if(env)env.oninput=()=>{record.plan.byCourse[activePlanCourse].environmentArrangement=env.value;dirty=true;state("Kaydedilmemiş değişiklik")};
 const courseTeacher=document.querySelector("#courseTeacher");if(courseTeacher)courseTeacher.oninput=()=>{record.plan.byCourse[activePlanCourse].teacher=courseTeacher.value;dirty=true;state("Kaydedilmemiş değişiklik")};
 document.querySelectorAll("[data-add-short]").forEach(el=>el.onclick=()=>{const rows=record.plan.byCourse[activePlanCourse].rows,i=Number(el.dataset.addShort),base=rows[i];rows.splice(i+1,0,Object.assign(goalRow(),{longTerm:base.longTerm,startMonth:base.startMonth,endMonth:base.endMonth}));dirty=true;render()});
 document.querySelectorAll("[data-remove-plan]").forEach(el=>el.onclick=()=>{const rows=record.plan.byCourse[activePlanCourse].rows;if(rows.length>1)rows.splice(Number(el.dataset.removePlan),1);dirty=true;render()});
 const addLong=document.querySelector("#addLongGoal");if(addLong)addLong.onclick=()=>{record.plan.byCourse[activePlanCourse].rows.push(goalRow());dirty=true;render()};
