 const addClass=document.querySelector("#addClass");if(addClass)addClass.onclick=()=>{school.classes.push({name:"",teacher:"",level:"",schedule:""});dirty=true;render()};
 const applyBulkSchedule=document.querySelector("#applyBulkSchedule");if(applyBulkSchedule)applyBulkSchedule.onclick=()=>{const level=document.querySelector("#bulkClassLevel").value,schedule=document.querySelector("#bulkClassSchedule").value;if(!level||!schedule){alert("Önce sınıf düzeyi ve eğitim saati seçin.");return}const matches=school.classes.filter(x=>x.level===level);if(!matches.length){alert("Seçilen sınıf düzeyinde kayıtlı sınıf bulunamadı.");return}matches.forEach(x=>x.schedule=schedule);dirty=true;render();toast(matches.length+" sınıfın eğitim saati güncellendi")};
 const nameFilter=document.querySelector("#studentNameFilter");if(nameFilter)nameFilter.oninput=()=>{searchName=nameFilter.value;render();const n=document.querySelector("#studentNameFilter");n.focus();n.setSelectionRange(searchName.length,searchName.length)};
 const classFilter=document.querySelector("#studentClassFilter");if(classFilter)classFilter.onchange=()=>{searchClass=classFilter.value;render()};
