 document.querySelectorAll("[data-goal-upload]").forEach(button=>button.onclick=()=>{const scope=button.dataset.goalUpload,password=prompt((scope==="global"?"Ortak":"Kullanıcı")+" amaç havuzu yükleme şifresini girin:");if(password===null)return;const expected=scope==="global"?"0000":"1111";if(password!==expected){alert("Şifre yanlış. Dosya yüklenmedi.");return}pendingGoalScope=scope;document.querySelector(scope==="global"?"#globalGoalInput":"#personalGoalInput").click()});
 [["globalGoalInput","global"],["personalGoalInput","personal"]].forEach(([id,scope])=>{const input=document.querySelector("#"+id);if(input)input.onchange=async()=>{const f=input.files[0];pendingGoalScope=scope;if(f)await prepareGoalImport(f);input.value=""}});
 const templateButton=document.querySelector("#downloadGoalTemplate");if(templateButton)templateButton.onclick=downloadGoalTemplate;
