 const archiveImportOnly=document.querySelector("#archiveImportOnly");if(archiveImportOnly)archiveImportOnly.onclick=async()=>{await saveImportArchive(false);pendingStudentImport=null;page="importArchives";render();toast("Karşılaştırma arşivlendi")};
 const applyStudentImport=document.querySelector("#applyStudentImport");if(applyStudentImport)applyStudentImport.onclick=async()=>{if(confirm("Yeni öğrenciler eklensin ve değişen engel türleri güncellensin mi? Eski listede olup yeni dosyada olmayan öğrenciler silinmez."))await applyPreparedStudentImport()};
 document.querySelectorAll("[data-download-archive]").forEach(el=>el.onclick=()=>{const a=importArchives.find(x=>x.id===el.dataset.downloadArchive);if(!a)return;const blob=new Blob([JSON.stringify(a,null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="ogrenci-listesi-karsilastirma-"+String(a.createdAt).slice(0,10)+".json";link.click();URL.revokeObjectURL(link.href);toast("Karşılaştırma kaydı indirildi")});
 const homeNew=document.querySelector("#homeNew");if(homeNew)homeNew.onclick=startNew;
 const ad=document.querySelector("#addDiagnosis");if(ad)ad.onclick=async()=>{const input=document.querySelector("#newDiagnosis"),x=input.value.trim();if(!x)return;if(!school.disabilityOptions.includes(x))school.disabilityOptions.push(x);school.disabilityOptions.sort((a,b)=>a.localeCompare(b,"tr"));record.student.diagnoses=[...new Set([...record.student.diagnoses,x])];await saveSchool();dirty=true;render()};
 const logo=document.querySelector("#logoInput");if(logo)logo.onchange=()=>{const f=logo.files[0];if(!f)return;if(f.size>1500000){alert("Logo dosyası 1,5 MB'den küçük olmalıdır.");return}const reader=new FileReader();reader.onload=()=>{school.logo=reader.result;dirty=true;render()};reader.readAsDataURL(f)};
 const removeLogo=document.querySelector("#removeLogo");if(removeLogo)removeLogo.onclick=()=>{school.logo="";dirty=true;render()};
