document.querySelector("#exportBtn").onclick=()=>{const blob=new Blob([JSON.stringify({version:4,school,records,globalGoalLibrary,personalGoalLibrary,importArchives},null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="BEP-veritabani-yedek.json";a.click();URL.revokeObjectURL(a.href);toast("Veritabanı yedeği indirildi")};
document.querySelector("#importInput").onchange=async ev=>{try{const x=JSON.parse(await ev.target.files[0].text());if(x.school){school=Object.assign(school,x.school);await saveSchool()}if(Array.isArray(x.globalGoalLibrary)||Array.isArray(x.goalLibrary))await req(tx(SETTINGS,"readwrite").put({key:"globalGoalLibrary",value:x.globalGoalLibrary||x.goalLibrary}));if(Array.isArray(x.personalGoalLibrary))await req(tx(SETTINGS,"readwrite").put({key:"personalGoalLibrary",value:x.personalGoalLibrary}));if(Array.isArray(x.importArchives))await req(tx(SETTINGS,"readwrite").put({key:"importArchives",value:x.importArchives}));if(Array.isArray(x.records))for(const r of x.records)await req(tx(STORE,"readwrite").put(merge(emptyRecord(),r)));await loadAll();page="students";render();toast("Veritabanı geri yüklendi")}catch{alert("JSON yedeği okunamadı.")}ev.target.value=""};
function remindTodayMeetings(){const meetings=records.filter(x=>x.meeting?.planDay===today()&&x.meeting?.time).sort((a,b)=>String(a.meeting.time).localeCompare(String(b.meeting.time)));if(!meetings.length)return;const lines=meetings.map(x=>x.meeting.time+" · "+x.student.name+" · "+x.student.classBranch+" · "+appointmentPlace(x));setTimeout(()=>alert("Bugün "+meetings.length+" BEP toplantısı var:\n\n"+lines.join("\n")),150)}
(async()=>{try{db=await openDb();await loadAll();if(location.hash==="#ogretmen-girisi")page="teacherLogin";render();remindTodayMeetings()}catch(e){document.querySelector("#app").innerHTML="<article class='card'><div class='card-body'><h2>Yerel veritabanı açılamadı</h2><p>"+esc(e.message)+"</p></div></article>"}})();
